func (q *Quoter) Quote(ctx context.Context, legs []Leg) (Quote, error) {
	var total Money
	for _, leg := range legs {
		fare, err := q.store.FareFor(ctx, leg.RouteID, leg.Class)
		if err != nil {
			return Quote{}, err
		}
		total = total.Add(fare.Price(leg.Party))
	}
	return Quote{Total: total}, nil
}
